const c=require("./.lattice/story/actives/B-137a/checklist.json");
const items=c.items||c;
for(const it of items){
  const vi=it.verificationIntent||{};
  const refs=new Set();
  for(const k of ["happy","edge","adversarial"]) for(const i of (vi[k]||[])) refs.add(i.id);
